mapper.sql:
SELECT ROW_NUMBER() OVER(ORDER BY S.REG_DTTM DESC) AS LINE_NO , S.SBJCT_ID , S.CRCLMN_NO AS SBJCT_CD , S.SBJCTNM , S.DVCLAS_NO , S.SBJCT_YR , S.SBJCT_SMSTR , S.SMSTR_CHRT_ID , SC.SMSTR_CHRT_GBNCD , S.USEYN , SC.ORG_ID , ORG.ORGNM FROM TB_LMS_SBJCT S JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = SC.ORG_ID WHERE S.DELYN = 'N' AND S.USEYN = 'Y' AND SC.ORG_ID = #{orgId}
AND S.SMSTR_CHRT_ID = #{smstrChrtId}
AND S.SBJCT_YR = #{sbjctYr}
AND TRIM(S.SBJCT_SMSTR) = #{sbjctSmstr}
AND ( S.SBJCTNM LIKE FN_LIKE_VAL(#{searchValue}) OR S.CRCLMN_NO LIKE FN_LIKE_VAL(#{searchValue}) )
ORDER BY S.REG_DTTM DESC

mapper.update:
/*
    SQL ID : ContsDAO.updateAdmLctrWknoSchdl
    설  명 : 강의주차일정 수정
*/
UPDATE TB_LMS_LCTR_WKNO_SCHDL W
   SET W.LCTR_WKNONM = #{lctrWknonm}
     , W.LCTR_WKNO_SYMD = #{lctrWknoSymd}
     , W.LCTR_WKNO_EYMD = #{lctrWknoEymd}
     , W.WKNO_ATNDC_RCG_SYMD = #{wknoAtndcRcgSymd}
     , W.WKNO_ATNDC_RCG_EYMD = #{wknoAtndcRcgEymd}
     , W.MDFR_ID = #{mdfrId}
     , W.MOD_DTTM = FN_DTTM()
 WHERE W.LCTR_WKNO_SCHDL_ID = #{lctrWknoSchdlId}
   AND W.SBJCT_ID = #{sbjctId}
   AND W.DELYN = 'N'
   AND EXISTS (
       SELECT 1
         FROM TB_LMS_SBJCT S
         JOIN TB_LMS_SMSTR_CHRT SC
           ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID
        WHERE S.SBJCT_ID = W.SBJCT_ID
          AND S.DELYN = 'N'
          AND SC.ORG_ID = #{orgId}
   )

mapper.insert:
/*
    SQL ID : ContsDAO.insertAdmLctrConts
    설  명 : 관리자 학습목차 콘텐츠 등록
*/
INSERT INTO TB_LMS_LCTR_CONTS (
      LCTR_CONTS_ID
    , LCTR_ID
    , CONTS_SEQNO
    , UP_LCTR_CONTS_ID
    , CONTS_FILE_ID
    , CONTSNM
    , LCTR_CONTS_TYCD
    , CONTS_URL
    , CONTS_PATH
    , CONTS_PSTN_CD
    , CONTS_FILE_EXT
    , VDO_MNTS
    , VDO_QLTY_GBNCD
    , ATNDC_RFLTYN
    , OYN
    , EXRCS_QSTN_ID
    , RGTR_ID
    , REG_DTTM
    , SDDN_QSTN_ID
    , SDDN_QSTN_PLY_SEC
    , LANG_CD
    , HTML_SRC
    , LRN_TOC_TTL
    , LRN_TOC_CTS
    , ADM_REG_CONTSYN
    , DELYN
) VALUES (
      #{lctrContsId}
    , #{lctrId}
    , #{contsSeqno}
    , #{upLctrContsId}
    , NVL(#{contsFileId}, 'NONE')
    , #{contsnm}
    , #{lctrContsTycd}
    , NVL(#{contsUrl}, '-')
    , NVL(#{contsPath}, '-')
    , NVL(#{contsPstnCd}, 'LOCAL')
    , #{contsFileExt}
    , #{vdoMnts}
    , #{vdoQltyGbncd}
    , NVL(#{atndcRfltyn}, 'N')
    , NVL(#{oyn}, 'Y')
    , #{exrcsQstnId}
    , #{rgtrId}
    , FN_DTTM()
    , #{sddnQstnId}
    , #{sddnQstnPlySec}
    , #{langCd}
    , #{htmlSrc,jdbcType=CLOB}
    , #{lrnTocTtl}
    , #{lrnTocCts,jdbcType=CLOB}
    , NVL(#{admRegContsyn}, 'Y')
    , NVL(#{delyn}, 'N')
)

/*
    SQL ID : ContsDAO.insertAdmLctrContsBatch
    설  명 : 관리자 학습목차 콘텐츠 일괄 등록
*/
INSERT ALL

    INTO TB_LMS_LCTR_CONTS (
          LCTR_CONTS_ID
        , LCTR_ID
        , CONTS_SEQNO
        , UP_LCTR_CONTS_ID
        , CONTS_FILE_ID
        , CONTSNM
        , LCTR_CONTS_TYCD
        , CONTS_URL
        , CONTS_PATH
        , CONTS_PSTN_CD
        , CONTS_FILE_EXT
        , VDO_MNTS
        , VDO_QLTY_GBNCD
        , ATNDC_RFLTYN
        , OYN
        , EXRCS_QSTN_ID
        , RGTR_ID
        , REG_DTTM
        , SDDN_QSTN_ID
        , SDDN_QSTN_PLY_SEC
        , LANG_CD
        , HTML_SRC
        , LRN_TOC_TTL
        , LRN_TOC_CTS
        , ADM_REG_CONTSYN
        , DELYN
    ) VALUES (
          #{item.lctrContsId}
        , #{item.lctrId}
        , #{item.contsSeqno}
        , #{item.upLctrContsId}
        , NVL(#{item.contsFileId}, 'NONE')
        , #{item.contsnm}
        , #{item.lctrContsTycd}
        , NVL(#{item.contsUrl}, '-')
        , NVL(#{item.contsPath}, '-')
        , NVL(#{item.contsPstnCd}, 'LOCAL')
        , #{item.contsFileExt}
        , #{item.vdoMnts}
        , #{item.vdoQltyGbncd}
        , NVL(#{item.atndcRfltyn}, 'N')
        , NVL(#{item.oyn}, 'Y')
        , #{item.exrcsQstnId}
        , #{item.rgtrId}
        , FN_DTTM()
        , #{item.sddnQstnId}
        , #{item.sddnQstnPlySec}
        , #{item.langCd}
        , #{item.htmlSrc,jdbcType=CLOB}
        , #{item.lrnTocTtl}
        , #{item.lrnTocCts,jdbcType=CLOB}
        , NVL(#{item.admRegContsyn}, 'Y')
        , NVL(#{item.delyn}, 'N')
    )

SELECT 1 FROM DUAL

