/*
    SQL ID : ContsDAO.updateAdmLctrConts
    설  명 : 관리자 학습목차 콘텐츠 수정
*/
UPDATE TB_LMS_LCTR_CONTS C
   SET C.CONTSNM = #{contsnm}
     , C.CONTS_SEQNO = #{contsSeqno}
     , C.LCTR_CONTS_TYCD = #{lctrContsTycd}
     , C.CONTS_URL = NVL(#{contsUrl}, '-')
     , C.CONTS_PATH = NVL(#{contsPath}, '-')
     , C.CONTS_PSTN_CD = NVL(#{contsPstnCd}, 'LOCAL')
     , C.CONTS_FILE_EXT = #{contsFileExt}
     , C.VDO_MNTS = #{vdoMnts}
     , C.VDO_QLTY_GBNCD = #{vdoQltyGbncd}
     , C.ATNDC_RFLTYN = NVL(#{atndcRfltyn}, 'N')
     , C.OYN = NVL(#{oyn}, 'Y')
     , C.EXRCS_QSTN_ID = #{exrcsQstnId}
     , C.SDDN_QSTN_ID = #{sddnQstnId}
     , C.SDDN_QSTN_PLY_SEC = #{sddnQstnPlySec}
     , C.LANG_CD = #{langCd}
     , C.HTML_SRC = #{htmlSrc,jdbcType=CLOB}
     , C.LRN_TOC_TTL = #{lrnTocTtl}
     , C.LRN_TOC_CTS = #{lrnTocCts,jdbcType=CLOB}
     , C.ADM_REG_CONTSYN = NVL(#{admRegContsyn}, 'Y')
     , C.MDFR_ID = #{mdfrId}
     , C.MOD_DTTM = FN_DTTM()
 WHERE C.LCTR_CONTS_ID = #{lctrContsId}
   AND C.DELYN = 'N'
   AND EXISTS (
       SELECT 1
         FROM TB_LMS_LCTR L
         JOIN TB_LMS_LCTR_WKNO_SCHDL W
           ON W.LCTR_WKNO_SCHDL_ID = L.LCTR_WKNO_SCHDL_ID
          AND W.DELYN = 'N'
         JOIN TB_LMS_SBJCT S
           ON S.SBJCT_ID = W.SBJCT_ID
          AND S.DELYN = 'N'
         JOIN TB_LMS_SMSTR_CHRT SC
           ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID
        WHERE L.LCTR_ID = C.LCTR_ID
          AND L.DELYN = 'N'
          AND SC.ORG_ID = #{orgId}
   )

mapper.select:
/* SQL ID : ContsDAO.selectAdmSddnQstnList 설 명 : 관리자 학습목차 돌발퀴즈 선택 목록 조회 */
SELECT ROW_NUMBER() OVER(ORDER BY QSTN_BSC.REG_DTTM DESC) AS LINE_NO , QSTN_BSC.EXRCS_SDDN_QSTN_BSC_ID , QSTN_BSC.SBJCT_ID , S.SBJCTNM , QSTN_BSC.QSTN_TTL , QSTN_BSC.QSTN_GBNCD , QSTN_BSC.QSTNS_CMPTNYN , (SELECT COUNT(1) FROM TB_LMS_QSTN Q WHERE Q.DELYN = 'N' AND Q.EXRCS_SDDN_QSTN_BSC_ID = QSTN_BSC.EXRCS_SDDN_QSTN_BSC_ID AND Q.QSTN_GBNCD = QSTN_BSC.QSTN_GBNCD) AS QSTN_CNT , QSTN_BSC.REG_DTTM , COUNT(1) OVER() AS TOTAL_CNT FROM TB_LMS_EXRCS_SDDN_QSTN_BSC QSTN_BSC JOIN TB_LMS_SBJCT S ON S.SBJCT_ID = QSTN_BSC.SBJCT_ID AND S.DELYN = 'N' JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID WHERE QSTN_BSC.QSTN_GBNCD = 'SURPRISE_QUIZ' AND QSTN_BSC.DELYN = 'N' AND QSTN_BSC.QSTNS_CMPTNYN = 'Y' AND SC.ORG_ID = #{orgId}
AND QSTN_BSC.SBJCT_ID = #{sbjctId}
AND QSTN_BSC.QSTN_TTL LIKE FN_LIKE_VAL(#{searchValue})
ORDER BY QSTN_BSC.REG_DTTM DESC

/* SQL ID : ContsDAO.selectAdmExrcsQstnList 설명 : 관리자 학습목차 연습문제 선택 목록 조회 */
SELECT ROW_NUMBER() OVER(ORDER BY QSTN_BSC.REG_DTTM DESC) AS LINE_NO , QSTN_BSC.EXRCS_SDDN_QSTN_BSC_ID , QSTN_BSC.SBJCT_ID , S.SBJCTNM , S.DVCLAS_NO , S.SMSTR_CHRT_ID , SC.DGRS_YR , SC.DGRS_SMSTR_CHRT , SC.SMSTR_CHRT_GBNCD , CASE WHEN NVL(SC.SMSTR_CHRT_GBNCD, 'SMSTR') = 'SMSTR' THEN SC.DGRS_YR || '년도 ' || SC.DGRS_SMSTR_CHRT || '학기' ELSE SC.DGRS_YR || '년도 ' || SC.DGRS_SMSTR_CHRT || '기수' END AS YR_SMSTRNM , QSTN_BSC.QSTN_TTL , QSTN_BSC.QSTN_GBNCD , QSTN_BSC.QSTNS_CMPTNYN , (SELECT COUNT(1) FROM TB_LMS_QSTN Q WHERE Q.DELYN = 'N' AND Q.EXRCS_SDDN_QSTN_BSC_ID = QSTN_BSC.EXRCS_SDDN_QSTN_BSC_ID AND Q.QSTN_GBNCD = QSTN_BSC.QSTN_GBNCD) AS QSTN_CNT , QSTN_BSC.REG_DTTM , COUNT(1) OVER() AS TOTAL_CNT FROM TB_LMS_EXRCS_SDDN_QSTN_BSC QSTN_BSC JOIN TB_LMS_SBJCT S ON S.SBJCT_ID = QSTN_BSC.SBJCT_ID AND S.DELYN = 'N' JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID WHERE QSTN_BSC.QSTN_GBNCD = 'EXRCS_QSTN' AND QSTN_BSC.DELYN = 'N' AND QSTN_BSC.QSTNS_CMPTNYN = 'Y' AND SC.ORG_ID = ( SELECT CUR_SC.ORG_ID FROM TB_LMS_SBJCT CUR JOIN TB_LMS_SMSTR_CHRT CUR_SC ON CUR_SC.SMSTR_CHRT_ID = CUR.SMSTR_CHRT_ID WHERE CUR.SBJCT_ID = #{sbjctId} AND CUR.DELYN = 'N' )
AND S.SMSTR_CHRT_ID = #{smstrChrtId}
AND QSTN_BSC.SBJCT_ID = #{searchSbjctId}
AND S.DVCLAS_NO = #{dvclasNo}
AND QSTN_BSC.QSTN_TTL LIKE FN_LIKE_VAL(#{searchValue})
ORDER BY QSTN_BSC.REG_DTTM DESC

mapper.update:
/*
    SQL ID : ContsDAO.updateAdmLctrWknoOyn
    설  명 : 강의주차 공개여부 수정
*/
UPDATE TB_LMS_LCTR_WKNO_SCHDL W
   SET W.OYN = #{oyn}
     , W.MDFR_ID = #{mdfrId}
     , W.MOD_DTTM = FN_DTTM()
 WHERE W.LCTR_WKNO_SCHDL_ID = #{lctrWknoSchdlId}
   AND W.DELYN = 'N'
   AND EXISTS (
       SELECT 1
         FROM TB_LMS_SBJCT S
         JOIN TB_LMS_SMSTR_CHRT SC
           ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID
        WHERE S.SBJCT_ID = W.SBJCT_ID
          AND S.DELYN = 'N'
          AND SC.ORG_ID = #{orgId}
   )

/*
    SQL ID : ContsDAO.updateAdmLctrWknoSeqLrnyn
    설  명 : 강의주차 순차학습여부 수정
*/
UPDATE TB_LMS_LCTR_WKNO_SCHDL W
   SET W.SEQ_LRNYN = #{seqLrnyn}
     , W.MDFR_ID = #{mdfrId}
     , W.MOD_DTTM = FN_DTTM()
 WHERE W.LCTR_WKNO_SCHDL_ID = #{lctrWknoSchdlId}
   AND W.DELYN = 'N'
   AND EXISTS (
       SELECT 1
         FROM TB_LMS_SBJCT S
         JOIN TB_LMS_SMSTR_CHRT SC
           ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID
        WHERE S.SBJCT_ID = W.SBJCT_ID
          AND S.DELYN = 'N'
          AND SC.ORG_ID = #{orgId}
   )
